const bridgeUrl = ($json.body?.bridgeUrl || $env.REMIX_BRIDGE_URL || 'http://127.0.0.1:8787').replace(/\/+$/, '');
const input = $json.body || $json;
const command = input.command || 'send-selfie';
const requestedAction = String(input.action || input.mode || '').toLowerCase();
if (requestedAction === 'generate' && input.yes !== true && input.confirm !== true) {
  throw new Error('Refusing to spend Remix.Camera credits without yes=true.');
}
const action = requestedAction === 'generate' || (input.yes === true && input.preview !== true && input.dryRun !== true) ? 'generate' : 'dry-run';
const prompt = input.prompt || input.text || input.chatText || '';
const body = Object.fromEntries(Object.entries({
  profileId: input.profileId || $env.REMIX_PROFILE_ID,
  characterName: input.characterName || $env.REMIX_CHARACTER_NAME || 'Remix Companion',
  visualIdentity: input.visualIdentity || $env.REMIX_CHARACTER_VISUAL_IDENTITY,
  chatText: input.chatText || prompt,
  mood: input.mood || prompt,
  location: input.location || prompt,
  outfit: input.outfit,
  sourceImageUrl: input.sourceImageUrl,
  userReferenceImageUrl: input.userReferenceImageUrl,
  userConsent: input.userConsent,
  userDescription: input.userDescription,
  matureContent: input.matureContent === true || command === 'private-snap' ? true : undefined,
  theme: input.theme,
  maxGenerations: input.maxGenerations,
  snapTtlSeconds: input.snapTtlSeconds,
  yes: action === 'generate' ? true : undefined,
}).filter(([, value]) => value !== undefined && value !== null && value !== ''));
return [{ json: { bridgeUrl, command, action, body } }];

const payload = $json;
const imageUrls = Array.isArray(payload.results)
  ? payload.results.map((item) => item.imageUrl || item.productionImageUrl).filter(Boolean)
  : [];
const template = payload.promptTemplate?.packTitle || payload.promptTemplate?.packId || 'Remix.Camera template';
const text = payload.dryRun
  ? `Preview ready: ${template}\n\n${payload.prompt || ''}`
  : payload.markdown || payload.prompt || JSON.stringify(payload);
return [{ json: { text, imageUrls, payload, dryRun: payload.dryRun === true } }];
